29	
30	    /** Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. */
31	    private static final Map<String, int[]> REGION_RANGE = Map.of(
32	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
