43	            if (existing.getCustomerCode() != null) {
44	                taken.add(existing.getCustomerCode());
45	            }
46	        }
47	
48	        String code = base;
49	        for (int n = 2; taken.contains(code); n++) {
50	            code = base + "-" + n;
51	        }
52	        owner.setCustomerCode(code);
53	    }
54	
55	    /** The region whose inclusive range contains {@code postcode}, or {@code UNKNOWN} when the
56	     *  postcode is absent, not four digits, or in no known range. */
57	    private static String regionOf(String postcode) {
58	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
59	            return UNKNOWN;
60	        }
61	        int value = Integer.parseInt(postcode);
62	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
63	            int[] range = entry.getValue();
64	            if (value >= range[0] && value <= range[1]) {
65	                return entry.getKey();
66	            }
67	        }
68	        return UNKNOWN;
69	    }
70	
71	    /** The first 8 upper-case hex characters (4 bytes) of {@code SHA-256(value)}. */
72	    private static String hash8(String value) {
73	        try {
74	            byte[] digest = MessageDigest.getInstance("SHA-256")
75	                    .digest(value.getBytes(StandardCharsets.UTF_8));
76	            StringBuilder sb = new StringBuilder(8);
77	            for (int i = 0; i < 4; i++) {
78	                sb.append(String.format("%02X", digest[i]));
79	            }
80	            return sb.toString();
81	        }
82	        catch (Exception ex) {
83	            throw new IllegalStateException("SHA-256 unavailable", ex);
